local RewardSelect = Class("RewardSelect")
function RewardSelect:__init()
    self.data = {}
    --self.selectIndex = nil
    self.selectRewardId = nil
    self.getCB = nil
    self.openType = 0
    self.isGet = false

end

function RewardSelect:__delete()
    self.data = nil
    --self.selectIndex = nil
    self.selectRewardId = nil
    self.getCB = nil
    self.openType = nil
    self.isGet = nil


    self.controller = nil
end

function RewardSelect:Awake()
    KTool.SetActive(self.BtnReceiveReward, checkInt(self.selectRewardId) > 0)
    SetButtonAction(self.BtnReceiveReward, function ()
        if checkInt(self.openType) == 1 then
            if checkInt(self.selectRewardId) <= 0 then
                GameUtils.Toast(localize("请先选择心仪的武装"))
            else
                GameUtils.Request(
                    Interfaces.RookieDrawFinalPrize,
                    { prizeId = self.selectRewardId },
                    function(request, response)
                        if checkInt(response.errCode) == 0 then
                            local data = response.data
                            --if self.getCB then
                            --    self.getCB()
                            --end

                            KCookie.Set("BeginnerRewardSelectDrawData", data)
                            GoodsUtils.DrawRewards(data.rewards)
                            UIModule.BackDialog()

                        end
                    end)
            end
        else
            if not self.isGet then
                GameUtils.Toast(localize("大奖就在眼前，请继续努力~"))
            end
        end
    end)

    for index = 1, 4 do
        local roleNameNode = self['BtnRoleNameNode'..index]
        KTool.SetActive(roleNameNode, false)
    end
    CoWait.Start():Coroutine(util.cs_generator(function()
        coroutine.yield( CS.UnityEngine.WaitForSeconds(0.6) )
        for index = 1, 4 do
            local roleNameNode = self['BtnRoleNameNode'..index]
            KTool.SetActive(roleNameNode, true)
            local env = CfUtils.GetLuaScr(roleNameNode, "Game.UI.Common.CommonBtnRoleNameNode")
            if env then
                env:PlayAnimation("Go")
            end
        end
    end))
end

function RewardSelect:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, true)
        if not isNull(self.controller.Argument.parameters) then
            --if not isNull(self.controller.Argument.parameters.getCB) then
            --    self.getCB = self.controller.Argument.parameters.getCB
            --end
            if not isNull(self.controller.Argument.parameters.openType) then
                self.openType = self.controller.Argument.parameters.openType
            end
            if not isNull(self.controller.Argument.parameters.isGet) then
                self.isGet = self.controller.Argument.parameters.isGet
            end
            --if not isNull(self.controller.Argument.parameters.jumpCB) then
            --    self.clickCB = self.controller.Argument.parameters.jumpCB
            --end
        end
        self.data = self:GetBigPrizeVoList()
        KTool.SetActive(self.ReceiveReward, self.openType == OPENTYPE.Drawn)
        KTool.SetActive(self.NotCompleted, self.openType == OPENTYPE.Preview)
        CfUtils.FillText(self.NotCompleted:Find("Text"), self.isGet and localize("已领取") or localize("任务未完成"))

        self:FreshBaseUI()

    end))
    return coWait
end

function RewardSelect:FreshBaseUI()
    for i, v in pairs(self.data) do
        --region nameNode
        local env = CfUtils.GetLuaScr(self["BtnRoleNameNode"..v.rewardId], "Game.UI.Common.CommonBtnRoleNameNode")
        if env then
            env:RefreshSelf(v.reward, nil, function()
                --if self.clickCB then
                --    self.clickCB()
                --end
                KTool.SetActive(self.controller.gameObject, false)
            end, true)
        end
        --endregion
        SetButtonAction(self["RoleNode"..v.rewardId], function ()
            KTool.SetActive(self.BtnReceiveReward, true)
            if v.rewardId ~= self.selectRewardId then
                if not isNull(self.selectRewardId) then
                    KTool.SetActive(self["SelectRoleNode"..self.selectRewardId], false)
                end
                KTool.SetActive(self["SelectRoleNode"..v.rewardId], true)
                CfUtils.PlayAnimator(self.Container, "Choose"..v.rewardId)
                CfUtils.PlayDelayShowAnimate(self.BtnAnimRoot, 1, 0.3, 0, "RewardSelectBth")

                if env then
                    env:PlayDelayAnim(1, 0.3)
                end
                self.selectRewardId = v.rewardId

                for index = 1, 4 do
                    local node = self['RoleNode'..index].transform:Find("ImgRole")
                    node:GetComponent(typeof(CS.Engine.UI.UIGrayGraphics)):MarkGray(index ~= self.selectRewardId)
                end
            end
        end)
    end

end

---获得七日大奖表
function RewardSelect:GetBigPrizeVoList()
    local voList = CfUtils.GetWholeVo(AutoIds.IdSetting920, "SevenDaysBigPrizeVo")
    table.sort(voList, function (a,b)--按奖励编号进行排序
        if a.rewardId ~= b.rewardId then
            return a.rewardId < b.rewardId
        end
    end)
    return voList
end

function RewardSelect:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return RewardSelect